if file.Exists("lunar_shade_locked.txt", "DATA") then pcall(file.Write, "lunar_shade_menu_status.txt", "locked: the release check failed (see lunar_shade_verify in a game)") MsgC(Color(255, 150, 120), "[Lunar Shade menu] ", Color(255, 255, 255), "locked: this copy failed the signed release check, so the custom menu is off. Download Lunar Shade again from the official page.\n") return end local LS_VERSION = "1.0.0" local LS_AUTHOR = "OfficialRealGahdly" pcall(file.Write, "lunar_shade_menu_status.txt", "loading: boot file is running") pcall(file.Write, "lunar_shade_status_loading.txt", "loading") pcall(function() for _, f in ipairs(file.Find("lunar_shade_menuver_*", "DATA") or {}) do file.Delete(f) end file.Write("lunar_shade_menuver_" .. (LS_VERSION:gsub("%.", "_")) .. ".txt", LS_VERSION) end) LunarShade = LunarShade or {} LunarShadeMenu = LunarShadeMenu or {} local Boot = {} LunarShadeMenu.Boot = Boot LunarShadeMenu.Author = LS_AUTHOR Boot.Version = LS_VERSION Boot.Mode = "title" Boot.Failures = 0 local function ls_compile(src, name)
 local cs = rawget(_G, "CompileString")
 if cs then
  local fn = cs(src, name, false)
  if type(fn) == "function" then return fn end
  error("compile failed for " .. name .. ": " .. tostring(fn), 0)
 end
 local ld = rawget(_G, "loadstring") or rawget(_G, "load")
 if ld then
  local fn, err = ld(src, "@" .. name)
  if not fn then error("compile failed for " .. name .. ": " .. tostring(err), 0) end
  return fn
 end
 local rs = rawget(_G, "RunString")
 if rs then return function() return rs(src, name) end end
 error("no way to compile Lua in the menu state", 0)
end
local function ls_read(f)
 local tried = {}
 local function try(path, g)
  local d = file.Read(path, g)
  tried[#tried + 1] = g .. ":" .. path
  if d and #d > 0 then return d end
 end
 local d = try(f, "LUA") or try("lua/" .. f, "GAME") or try("lua/" .. f, "MOD")
 if d then return d end
 local _, dirs = file.Find("addons/*", "GAME")
 for _, dn in ipairs(dirs or {}) do
  d = try("addons/" .. dn .. "/lua/" .. f, "GAME")
  if d then return d end
 end
 return nil, table.concat(tried, ", ")
end
local function load_modules() if not rawget(_G, "draw") then pcall(require, "draw") end if not rawget(_G, "draw") then pcall(include, "includes/modules/draw.lua") end assert(rawget(_G, "draw"), "the 'draw' library is not available in the menu state") if not (LunarShade.Crypt and LunarShade.Crypt.Decrypt) then pcall(include, "lunar_shade/sh_crypt.lua") end
 if not (LunarShade.Crypt and LunarShade.Crypt.Decrypt) then
  local craw = ls_read("lunar_shade/sh_crypt.lua")
  if craw then ls_compile(craw, "lunar_shade/sh_crypt.lua")() end
