 assert(LunarShade.Crypt.Scheme == "chacha20-poly1305", "an old lunar_shade/sh_crypt.lua is installed - run Install-MainMenu again")
 for _, f in ipairs({ "lunar_shade/sh_presets.lua", "lunar_shade_menu/mn_settings.lua", "lunar_shade_menu/mn_scene.lua", "lunar_shade_menu/mn_title.lua", "lunar_shade_menu/mn_tutorial.lua", "lunar_shade_menu/mn_html.lua", "lunar_shade_menu/mn_pages.lua" }) do local raw, why = ls_read(f) assert(raw, "could not read " .. f .. " (tried " .. tostring(why) .. ")") local src, derr = LunarShade.Crypt.Decrypt(raw, f) assert(src, "could not decrypt " .. f .. ": " .. tostring(derr) .. " - run Install-MainMenu again") local chunk = ls_compile(src, f) chunk() end end function Boot.ClickStock(label) local menu = rawget(_G, "pnlMainMenu") if not label or not (menu and IsValid(menu) and menu.HTML and IsValid(menu.HTML)) then return false end local js = "(function(){var t='" .. string.lower(label) .. "';var n=document.querySelectorAll('a,li,div,span,button');" .. "for(var i=0;i<n.length;i++){var e=n[i];if(e.children.length===0&&e.textContent.trim().toLowerCase()===t){e.click();return true;}}return false;})()" menu.HTML:RunJavascript(js) return true end function Boot.SetMode(mode, label) Boot.Mode = mode if mode == "classic" and label then timer.Simple(0.15, function() pcall(Boot.ClickStock, label) end) end end local function status(text) if LunarShadeMenu.Settings and Boot.LastStatus ~= text then Boot.LastStatus = text LunarShadeMenu.Settings.WriteStatus(text) end end local function remove(p) if p and IsValid(p) then p:Remove() end end function Boot.OpenTutorial(settings) remove(Boot.Tutorial) Boot.Tutorial = LunarShadeMenu.Tutorial.Open({ settings = settings, onFinish = function() LunarShadeMenu.Settings.MarkWelcomed() end, }) end function Boot.BuildTitle(settings) remove(Boot.Panel) Boot.Panel = LunarShadeMenu.Title.Create({ settings = settings, onClassic = function(label) Boot.SetMode("classic", label) end, onTutorial = function() Boot.OpenTutorial(settings) end, }) Boot.Panel.LS_W, Boot.Panel.LS_H = ScrW(), ScrH() Boot.Panel:MoveToFront() end function Boot.BuildReturn(settings) remove(Boot.Return) local P = LunarShadeMenu.Settings.Palette(settings) local b = vgui.Create("DButton") b:SetSize(190, 36) b:SetPos(180, ScrH() - 64) b:SetText("") b:SetCursor("hand") b.DoClick = function() Boot.SetMode("title") end b.Paint = function(s, w, h) surface.SetDrawColor(14, 15, 22, s:IsHovered() and 245 or 215) surface.DrawRect(0, 0, w, h) surface.SetDrawColor(P.accent) surface.DrawOutlinedRect(0, 0, w, h, 1) draw.SimpleText("< Lunar Shade menu", "LunarShadeMenu.Small", w / 2, h / 2, P.bright, TEXT_ALIGN_CENTER, TEXT_ALIGN_CENTER) end b:MoveToFront() Boot.Return = b end function Boot.OpenPage(id) local Pg, H = LunarShadeMenu.Pages, LunarShadeMenu.HTML if not (Pg and H) then return false end if Pg.OnOpen then pcall(Pg.OnOpen, id) end local page = Pg.Build(id) if not page then return false end Pg.Current = id H.PageOpen(page) return true end function Boot.PageMessage(msg) local Pg, H = LunarShadeMenu.Pages, LunarShadeMenu.HTML if not (Pg and H) then return end local id, action, value = msg:match("^([^|]*)|([^|]*)|?(.*)$") if not id then return end if id == "open" then Boot.OpenPage(action); return end local res = Pg.Act(id, action, value) if res == "close" then H.PageClose(); Pg.Current = nil; return end if res == "stockopts" then H.PageClose(); Pg.Current = nil; LunarShadeMenu.Title.RunCommand("OpenOptionsDialog"); return end if res == "stocklist" then H.StockProblemsClick(); return end if res == "norefresh" then return end local nxt = type(res) == "string" and res:match("^open:(.+)$") if nxt then Boot.OpenPage(nxt); return end if res == "stock" then H.PageClose(); Pg.Current = nil local label = ({ addons = "Addons", dupes = "Dupes", saves = "Saves", demos = "Demos", newgame = "Start New Game", servers = "Find Multiplayer Game" })[id] Boot.SetMode("classic", label) Boot.SyncHTML(LunarShadeMenu.Settings.Load(), true) return end if Pg.Current == id then local page = Pg.Build(id) if page then H.PageSet(page) end end end function Boot.SyncHTML(settings, show) local H = LunarShadeMenu.HTML if not H then return end if not show then H.Remove(); return end local welcomed = LunarShadeMenu.Settings.IsWelcomed() H.Sync({ settings = settings, mode = Boot.Mode, steps = LunarShadeMenu.Tutorial.Steps, wantTour = not welcomed and not H.TourOpen and not Boot.Pause, onDone = function() LunarShadeMenu.Settings.MarkWelcomed() end, onTour = function() H.ShowTour(LunarShadeMenu.Settings.Load(), LunarShadeMenu.Tutorial.Steps) end, onAct = function(i) if i == 0 then Boot.SetMode("classic"); Boot.SyncHTML(LunarShadeMenu.Settings.Load(), true); return end local it = (Boot.Pause and LunarShadeMenu.Title.PauseItems or LunarShadeMenu.Title.Items)[i] if type(it) ~= "table" then return end if it.page and LunarShadeMenu.Pages then Boot.OpenPage(it.page) elseif it.cmd then LunarShadeMenu.Title.RunCommand(it.cmd) elseif it.html then Boot.SetMode("classic", it.label); Boot.SyncHTML(LunarShadeMenu.Settings.Load(), true) end end, onBack = function() Boot.SetMode("title"); Boot.SyncHTML(LunarShadeMenu.Settings.Load(), true) end, onPage = function(msg) Boot.PageMessage(msg) end, }) if welcomed and H.TourOpen and not H.TourManual then H.HideTour() end if Boot.Mode ~= "classic" and LunarShadeMenu.Pages then H.BarSet(LunarShadeMenu.Pages.BarState()) end end function Boot.Tick() local settings = LunarShadeMenu.Settings.Load() local inGame = IsInGame and IsInGame() or false local sig = LunarShadeMenu.Settings.Signature(settings) local want = (inGame and settings.pause_enabled) or (not inGame and settings.menu_enabled) Boot.Pause = inGame and true or false if LunarShadeMenu.HTML then LunarShadeMenu.HTML.Pause = Boot.Pause end if not want then pcall(Boot.SyncHTML, settings, false) remove(Boot.Panel); Boot.Panel = nil remove(Boot.Return); Boot.Return = nil remove(Boot.Tutorial); Boot.Tutorial = nil Boot.Mode = "title" return end if Boot.Mode == "title" then remove(Boot.Return); Boot.Return = nil if Boot.Pause then remove(Boot.Panel); Boot.Panel = nil remove(Boot.Tutorial); Boot.Tutorial = nil Boot.Sig = nil else local stale = not (Boot.Panel and IsValid(Boot.Panel)) or Boot.Sig ~= sig or Boot.Panel.LS_W ~= ScrW() or Boot.Panel.LS_H ~= ScrH() if stale then Boot.Sig = sig Boot.BuildTitle(settings) end if not LunarShadeMenu.Settings.IsWelcomed() and not (Boot.Tutorial and IsValid(Boot.Tutorial)) then Boot.OpenTutorial(settings) end if Boot.Tutorial and IsValid(Boot.Tutorial) then Boot.Tutorial:MoveToFront() end end local Pg = LunarShadeMenu.Pages if Pg and Pg.Current == "options" and Pg.OptTab == "keyboard" and Pg.BindsLive and SysTime() - (Boot.KeyPoll or 0) > 1.5 then Boot.KeyPoll = SysTime() local before = {} for k, v in pairs(Pg.Binds or {}) do before[k] = v end Pg.ReadBinds() local changed = false for k, v in pairs(Pg.Binds) do if before[k] ~= v then changed = true end end for k, v in pairs(before) do if Pg.Binds[k] ~= v then changed = true end end if changed and LunarShadeMenu.HTML then LunarShadeMenu.HTML.PageSet(Pg.Build("options")) end end if Pg and (Pg.Current == "servers" or Pg.Current == "addons") and SysTime() - (Boot.ServerPush or 0) > (Pg.Current == "addons" and 2.5 or 1) and Pg.TakeDirty() then Boot.ServerPush = SysTime() local pg = Pg.Build(Pg.Current) if pg and LunarShadeMenu.HTML then LunarShadeMenu.HTML.PageSet(pg) end end if Boot.Panel and IsValid(Boot.Panel) then status("ready") end local okh, errh = pcall(Boot.SyncHTML, settings, true) local htxt = okh and ((LunarShadeMenu.HTML and LunarShadeMenu.HTML.Active) and "active" or "waiting for the menu page") or ("error: " .. tostring(errh)) if Boot.HtmlText ~= htxt then Boot.HtmlText = htxt; LunarShadeMenu.Settings.SetMarker("html", okh and ((LunarShadeMenu.HTML and LunarShadeMenu.HTML.Active) and "active" or "waiting") or "error", htxt) end if LunarShadeMenu.Settings.IsWelcomed() and Boot.Tutorial and IsValid(Boot.Tutorial) then remove(Boot.Tutorial); Boot.Tutorial = nil end else pcall(Boot.SyncHTML, settings, true) remove(Boot.Panel); Boot.Panel = nil if not (Boot.Return and IsValid(Boot.Return)) then Boot.BuildReturn(settings) end end end function Boot.Start() LunarShadeMenu.Attempts = (LunarShadeMenu.Attempts or 0) + 1 local ok, err = pcall(load_modules) if not ok then if LunarShadeMenu.Attempts < 6 then timer.Simple(3, Boot.Start) end MsgC(Color(240, 106, 126), "[Lunar Shade menu] ", Color(255, 255, 255), "could not load: " .. tostring(err) .. "\n") pcall(file.Write, "lunar_shade_menu_status.txt", "error: " .. tostring(err)) return end status("started") MsgC(Color(160, 130, 255), "[Lunar Shade menu] ", Color(255, 255, 255), "v" .. LS_VERSION .. " by " .. LS_AUTHOR .. " started.\n") timer.Create("LunarShadeMenu_Tick", 0.5, 0, function() local ok2, err2 = pcall(Boot.Tick) if not ok2 then Boot.Failures = Boot.Failures + 1 status("error: " .. tostring(err2)) remove(Boot.Panel); Boot.Panel = nil remove(Boot.Return); Boot.Return = nil MsgC(Color(240, 106, 126), "[Lunar Shade menu] ", Color(255, 255, 255), tostring(err2) .. "\n") if Boot.Failures >= 3 then timer.Remove("LunarShadeMenu_Tick") end end end) MsgC(Color(157, 125, 255), "[Lunar Shade menu] ", Color(255, 255, 255), "title screen plugin started.\n") end Boot.Start()

   	 	   	   			 	  	  	 	 	 	   	  	    	 	 	 	 	    	   	 		 	 	 	  	  	   	 	 	  		   	   	 	 	     	 	 	  		 	   	 	  	 		 	  		   	  	 			   		      	 			   		    